CREATE TABLE perfil (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, nome VARCHAR(50) NOT NULL UNIQUE, descricao VARCHAR(255));
CREATE TABLE usuario (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, nome VARCHAR(120) NOT NULL, username VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(120) NOT NULL UNIQUE, senha VARCHAR(255) NOT NULL, ativo BOOLEAN NOT NULL, ultimo_acesso TIMESTAMP);
CREATE TABLE usuario_perfil (usuario_id BIGINT NOT NULL REFERENCES usuario(id), perfil_id BIGINT NOT NULL REFERENCES perfil(id), PRIMARY KEY(usuario_id,perfil_id));
CREATE TABLE organizacao_militar (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, nome VARCHAR(200) NOT NULL, sigla VARCHAR(50) NOT NULL, codigo VARCHAR(30) NOT NULL UNIQUE, cidade VARCHAR(120), uf VARCHAR(2), ativa BOOLEAN NOT NULL);
CREATE TABLE tipo_municao (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, nome VARCHAR(100) NOT NULL UNIQUE, descricao VARCHAR(255));
CREATE TABLE municao (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, tipo_municao_id BIGINT NOT NULL REFERENCES tipo_municao(id), calibre VARCHAR(80) NOT NULL, descricao VARCHAR(255) NOT NULL, fabricante VARCHAR(150) NOT NULL, ativo BOOLEAN NOT NULL);
CREATE TABLE paiol (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, nome VARCHAR(200) NOT NULL, codigo VARCHAR(50) NOT NULL UNIQUE, organizacao_militar_id BIGINT NOT NULL REFERENCES organizacao_militar(id), endereco VARCHAR(255), observacao VARCHAR(500), ativo BOOLEAN NOT NULL);
CREATE TABLE lote_municao (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, municao_id BIGINT NOT NULL REFERENCES municao(id), lote VARCHAR(80) NOT NULL, virola VARCHAR(80), data_validade DATE NOT NULL, organizacao_proprietaria_id BIGINT NOT NULL REFERENCES organizacao_militar(id), ativo BOOLEAN NOT NULL, CONSTRAINT uk_lote_municao UNIQUE(municao_id,lote));
CREATE TABLE estoque_paiol (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, paiol_id BIGINT NOT NULL REFERENCES paiol(id), lote_municao_id BIGINT NOT NULL REFERENCES lote_municao(id), quantidade_atual INTEGER NOT NULL CHECK(quantidade_atual>=0), quantidade_reservada INTEGER NOT NULL CHECK(quantidade_reservada>=0 AND quantidade_reservada<=quantidade_atual), data_entrada TIMESTAMP NOT NULL, ultima_movimentacao TIMESTAMP NOT NULL, versao BIGINT, CONSTRAINT uk_estoque_paiol_lote UNIQUE(paiol_id,lote_municao_id));
CREATE TABLE militar (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, nome_completo VARCHAR(120) NOT NULL, identidade VARCHAR(50) NOT NULL UNIQUE, posto_graduacao VARCHAR(30) NOT NULL, organizacao_militar_id BIGINT NOT NULL REFERENCES organizacao_militar(id), secao VARCHAR(100), telefone VARCHAR(30), email VARCHAR(120), ativo BOOLEAN NOT NULL);
CREATE TABLE viatura (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, tipo VARCHAR(30) NOT NULL, modelo VARCHAR(120) NOT NULL, placa VARCHAR(20) NOT NULL UNIQUE, prefixo VARCHAR(30) NOT NULL, organizacao_militar_id BIGINT NOT NULL REFERENCES organizacao_militar(id), ativo BOOLEAN NOT NULL);
CREATE TABLE movimentacao (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, eb VARCHAR(50), diex VARCHAR(100) NOT NULL, data_solicitacao DATE, data_apanha DATE, data_alteracao DATE, data_execucao_atividade DATE, om_local_apanha_id BIGINT REFERENCES organizacao_militar(id), om_solicitante_id BIGINT REFERENCES organizacao_militar(id), om_destino_id BIGINT REFERENCES organizacao_militar(id), paiol_origem_id BIGINT REFERENCES paiol(id), paiol_destino_id BIGINT REFERENCES paiol(id), oficial_responsavel_paiol_id BIGINT REFERENCES militar(id), oficial_municao_solicitante_id BIGINT REFERENCES militar(id), tipo_municao_id BIGINT REFERENCES tipo_municao(id), quantidade_solicitada INTEGER, anexo_nome VARCHAR(255), anexo_tipo VARCHAR(120), anexo_conteudo BYTEA, oficial_responsavel_entrega_id BIGINT REFERENCES militar(id), oficial_responsavel_recebimento_id BIGINT REFERENCES militar(id), motivo_retirada VARCHAR(255), observacao VARCHAR(500), status VARCHAR(30) NOT NULL, usuario_criador_id BIGINT REFERENCES usuario(id), usuario_ultima_alteracao_id BIGINT REFERENCES usuario(id), data_hora_criacao TIMESTAMP NOT NULL, data_hora_ultima_alteracao TIMESTAMP NOT NULL);
CREATE TABLE movimentacao_viaturas_selecionadas (movimentacao_id BIGINT NOT NULL REFERENCES movimentacao(id), viatura_id BIGINT NOT NULL REFERENCES viatura(id), PRIMARY KEY(movimentacao_id,viatura_id));
CREATE TABLE movimentacao_escoltas_selecionadas (movimentacao_id BIGINT NOT NULL REFERENCES movimentacao(id), militar_id BIGINT NOT NULL REFERENCES militar(id), PRIMARY KEY(movimentacao_id,militar_id));
CREATE TABLE movimentacao_motoristas_selecionados (movimentacao_id BIGINT NOT NULL REFERENCES movimentacao(id), militar_id BIGINT NOT NULL REFERENCES militar(id), PRIMARY KEY(movimentacao_id,militar_id));
CREATE TABLE movimentacao_viatura (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, movimentacao_id BIGINT NOT NULL REFERENCES movimentacao(id), viatura_id BIGINT NOT NULL REFERENCES viatura(id));
CREATE TABLE movimentacao_escolta (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, movimentacao_id BIGINT NOT NULL REFERENCES movimentacao(id), militar_id BIGINT NOT NULL REFERENCES militar(id), observacao VARCHAR(255));
CREATE TABLE movimentacao_motorista (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, movimentacao_id BIGINT NOT NULL REFERENCES movimentacao(id), motorista_id BIGINT NOT NULL REFERENCES militar(id), viatura_id BIGINT REFERENCES viatura(id), observacao VARCHAR(255));
CREATE TABLE item_movimentacao (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, movimentacao_id BIGINT NOT NULL REFERENCES movimentacao(id), lote_municao_id BIGINT NOT NULL REFERENCES lote_municao(id), quantidade_solicitada INTEGER NOT NULL CHECK(quantidade_solicitada>0), quantidade_reservada INTEGER NOT NULL CHECK(quantidade_reservada>=0), quantidade_autorizada INTEGER NOT NULL CHECK(quantidade_autorizada>=0), quantidade_separada INTEGER NOT NULL CHECK(quantidade_separada>=0), quantidade_entregue INTEGER NOT NULL CHECK(quantidade_entregue>=0), quantidade_recebida INTEGER NOT NULL CHECK(quantidade_recebida>=0), justificativa VARCHAR(500), observacao VARCHAR(255));
CREATE TABLE reserva_estoque (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, item_movimentacao_id BIGINT NOT NULL REFERENCES item_movimentacao(id), estoque_paiol_id BIGINT NOT NULL REFERENCES estoque_paiol(id), quantidade INTEGER NOT NULL CHECK(quantidade>0), quantidade_consumida INTEGER NOT NULL CHECK(quantidade_consumida>=0), quantidade_liberada INTEGER NOT NULL CHECK(quantidade_liberada>=0), situacao VARCHAR(20) NOT NULL, data_hora_reserva TIMESTAMP NOT NULL, data_hora_separacao TIMESTAMP, data_hora_liberacao TIMESTAMP, data_hora_baixa TIMESTAMP, usuario_responsavel_id BIGINT REFERENCES usuario(id), CONSTRAINT uk_reserva_item UNIQUE(item_movimentacao_id));
CREATE TABLE devolucao (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, movimentacao_id BIGINT NOT NULL REFERENCES movimentacao(id), data_devolucao DATE NOT NULL, observacao VARCHAR(500), status VARCHAR(30) NOT NULL, anexo_nome VARCHAR(255), anexo_tipo VARCHAR(120), anexo_conteudo BYTEA);
CREATE TABLE item_devolucao (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, devolucao_id BIGINT NOT NULL REFERENCES devolucao(id), item_movimentacao_id BIGINT NOT NULL REFERENCES item_movimentacao(id), quantidade_consumida INTEGER NOT NULL CHECK(quantidade_consumida>=0), quantidade_devolvida INTEGER NOT NULL CHECK(quantidade_devolvida>=0), quantidade_estojo INTEGER NOT NULL CHECK(quantidade_estojo>=0), justificativa VARCHAR(500), processado BOOLEAN NOT NULL, data_hora_processamento_estoque TIMESTAMP, observacao VARCHAR(255), CONSTRAINT uk_item_devolucao UNIQUE(devolucao_id,item_movimentacao_id));
CREATE TABLE movimentacao_estoque (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, estoque_paiol_id BIGINT NOT NULL REFERENCES estoque_paiol(id), tipo VARCHAR(40) NOT NULL, quantidade INTEGER NOT NULL CHECK(quantidade>0), saldo_anterior INTEGER NOT NULL CHECK(saldo_anterior>=0), saldo_posterior INTEGER NOT NULL CHECK(saldo_posterior>=0), reservado_anterior INTEGER NOT NULL CHECK(reservado_anterior>=0), reservado_posterior INTEGER NOT NULL CHECK(reservado_posterior>=0), item_movimentacao_id BIGINT REFERENCES item_movimentacao(id), status_anterior VARCHAR(30), status_posterior VARCHAR(30), data_hora TIMESTAMP NOT NULL, movimentacao_id BIGINT REFERENCES movimentacao(id), devolucao_id BIGINT REFERENCES devolucao(id), usuario_responsavel_id BIGINT REFERENCES usuario(id), observacao VARCHAR(255));
CREATE TABLE registro_auditoria (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, criado_em TIMESTAMP NOT NULL, atualizado_em TIMESTAMP NOT NULL, usuario_id BIGINT REFERENCES usuario(id), entidade VARCHAR(120) NOT NULL, entidade_id BIGINT, acao VARCHAR(60) NOT NULL, descricao VARCHAR(500), data_hora TIMESTAMP NOT NULL, endereco_ip VARCHAR(80));

CREATE INDEX idx_movimentacao_data ON movimentacao(data_solicitacao);
CREATE INDEX idx_movimentacao_status ON movimentacao(status);
CREATE INDEX idx_historico_movimentacao ON movimentacao_estoque(movimentacao_id);
